-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.flight_leaderboard(p_from date, p_to date)
 RETURNS TABLE(creator_id uuid, name text, photo_url text, km numeric, flights bigint, airports text[], visited text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    p.id, p.name, p.photo_url,
    coalesce(sum(f.distance_km), 0)::numeric as km,
    count(f.id)                              as flights,
    coalesce(
      array_agg(distinct f.from_iata) filter (where f.from_iata is not null)
        || array_agg(distinct f.to_iata) filter (where f.to_iata is not null),
      '{}'
    ) as airports,
    -- Their own travel map, as published on their profile.
    coalesce(p.countries_visited, '{}') as visited
  from public.profiles p
  left join public.flights f
    on f.creator_id = p.id
   and f.share_with_community
   and f.flown_on <= least(p_to, current_date)
   and f.flown_on >= p_from
  where p.status = 'active'
    and coalesce(p.is_test, false) = false
    and p.deletion_requested_at is null
  group by p.id, p.name, p.photo_url, p.countries_visited
  -- Somebody with no flights in the window and no travel map has nothing to
  -- rank, and a leaderboard padded with zeroes is a directory.
  having count(f.id) > 0 or coalesce(array_length(p.countries_visited, 1), 0) > 0
$function$;
